const printPaper='<section id="report-print-paper"><header><h1>'+esc(storeName)+'</h1><h2>Laporan Penjualan</h2><p>Periode: '+esc(periodLabel)+'</p></header><div class="report-print-summary"><div><span>Omzet lunas</span><b>'+money(revenue)+'</b></div><div><span>Transaksi</span><b>'+count+'</b></div><div><span>Item terjual</span><b>'+Object.values(items).reduce((n,x)=>n+x,0)+'</b></div></div><h3>Rincian Transaksi Lunas</h3><table><thead><tr><th>Nomor</th><th>Tanggal</th><th>Metode</th><th class="num">Total</th></tr></thead><tbody>'+printRows+'</tbody></table><h3>Menu Terlaris</h3><table><thead><tr><th>Menu</th><th class="num">Terjual</th></tr></thead><tbody>'+printItems+'</tbody></table>'+(includeCash?'<h3>Catatan Kas (terpisah dari omzet penjualan)</h3><div class="report-print-summary"><div><span>Modal awal + kas masuk</span><b>'+money(cashInTotal)+'</b></div><div><span>Pengeluaran</span><b>'+money(cashOutTotal)+'</b></div></div><table><thead><tr><th>Tanggal</th><th>Jenis</th><th>Keterangan</th><th>Metode</th><th class="num">Nominal</th></tr></thead><tbody>'+cashRows+'</tbody></table>':'')+'<footer>Dicetak '+new Date().toLocaleString("id-ID")+'</footer></section>';
return '<div class="page-stack"><div class="page-heading"><div><h2>Laporan</h2><div class="hint">Ringkasan transaksi lunas · '+periodLabel+'</div></div></div><section class="panel report-filter"><h3>Periode Laporan</h3><div class="report-filter-row"><select class="field" id="report-range"><option value="today" '+(reportRange==="today"?"selected":"")+'>Hari Ini</option><option value="7d" '+(reportRange==="7d"?"selected":"")+'>7 Hari Terakhir</option><option value="30d" '+(reportRange==="30d"?"selected":"")+'>30 Hari Terakhir</option><option value="month" '+(reportRange==="month"?"selected":"")+'>Bulan Ini</option><option value="custom" '+(reportRange==="custom"?"selected":"")+'>Rentang Tanggal</option></select>'+(reportRange==="custom"?'<label>Dari<input class="field" type="date" id="report-start" value="'+esc(reportStartDate)+'" max="'+endToday+'"></label><label>Sampai<input class="field" type="date" id="report-end" value="'+esc(reportEndDate)+'" max="'+endToday+'"></label>':'')+(reportRange==="custom"?'<button type="button" class="btn" data-action="apply-report-range">Terapkan Rentang</button>':'')+'</div></section><section class="stats"><div class="card"><div class="label">Omzet</div><div class="value">'+money(revenue)+'</div></div><div class="card"><div class="label">Transaksi Lunas</div><div class="value">'+count+'</div></div><div class="card"><div class="label">Item Terjual</div><div class="value">'+Object.values(items).reduce((n,x)=>n+x,0)+'</div></div></section><section class="panel"><h3>Grafik Penjualan</h3><div class="hint">Omzet harian berdasarkan tanggal pembayaran</div>'+(paid.length?'<div class="report-chart"><svg viewBox="0 0 '+w+' '+h+'" role="img" aria-label="Grafik omzet harian"><line x1="'+left+'" y1="'+(top+plotH)+'" x2="'+(w-right)+'" y2="'+(top+plotH)+'" stroke="#dce5df"/>'+bars+'</svg></div>':'<div class="empty">Belum ada transaksi lunas pada periode ini.</div>')+'</section><section class="panel"><h3>Menu Terlaris</h3>'+(popular.length?popular.map(([name,qty])=>'<div class="line"><span>'+esc(name)+'</span><b>× '+qty+'</b></div>').join(""):'<div class="empty">Belum ada item terjual pada periode ini.</div>')+'</section><section class="panel report-print-options"><label class="report-include-cash"><input type="checkbox" id="report-include-cash" '+(reportIncludeCash?"checked":"")+'> Sertakan catatan kas (modal awal, kas masuk, dan pengeluaran)</label><div class="hint">Catatan kas akan dicetak sebagai bagian terpisah, tidak dijumlahkan ke omzet penjualan.</div><label class="report-paper-label">Ukuran kertas cetak<select class="field" id="report-paper-size"><option value="A4" '+(reportPaperSize==="A4"?"selected":"")+'>A4 · Laporan</option><option value="58" '+(reportPaperSize==="58"?"selected":"")+'>58 mm · Thermal</option><option value="80" '+(reportPaperSize==="80"?"selected":"")+'>80 mm · Thermal</option></select></label><button type="button" class="btn" data-action="print-report">Cetak Laporan</button><div class="hint">Tombol cetak hanya membuka pratinjau setelah ditekan. Memilih ukuran kertas tidak akan membuka printer.</div></section></div>'+printPaper
