function updateCashSummary(){const sub=subtotal(),disc=discountAmount(),t=total(),got=paymentInput===""?NaN:Number(paymentInput),diff=got-t;const vals=document.querySelectorAll("[data-cash-value]");if(vals[0])vals[0].textContent=money(sub);if(vals[1])vals[1].textContent="− "+money(disc);if(vals[2])vals[2].textContent=money(t);const label=document.querySelector(".change-box span"),value=document.getElementById("change-value");if(label)label.textContent=Number.isFinite(got)&&diff<0?"Kekurangan":"Kembalian";if(value)value.textContent=Number.isFinite(got)?money(Math.abs(diff)):"—";const button=document.querySelector('[data-action="checkout"]');if(button)button.disabled=!cart.length}
